mapper.select:
select id, principal_key, tenant_key, asset_id, idempotency_key, status, version, attempt_count,
       queued_at, started_at, completed_at, confirmed_at, last_error_code, last_error_message
  from cynexus_appl_market.portfolio_import_task
 where id = #{taskId}
   and principal_key = #{principalKey}
   and tenant_key = #{tenantKey}
   and deleted_at is null

select id, principal_key, tenant_key, asset_id, idempotency_key, status, version, attempt_count,
       queued_at, started_at, completed_at, confirmed_at, last_error_code, last_error_message
  from cynexus_appl_market.portfolio_import_task
 where principal_key = #{principalKey}
   and tenant_key = #{tenantKey}
   and idempotency_key = #{idempotencyKey}
   and deleted_at is null
